</head>
<body>
<canvas id="stage"></canvas>
<div id="hud">
  <div class="fps">FPS: <span id="fps">--</span></div>
  <div>mode: <span id="mode">Gouraud</span></div>
  <div class="keys"><kbd>W</kbd> wireframe &nbsp; <kbd>P</kbd> pause</div>
