<script>
'use strict';
/* ============================================================
   Minimal 3D pipeline on Canvas 2D — Gouraud-shaded cube.

   Pipeline per frame:
     1. Cube vertices (object space)
     2. Rotation matrices (X, Y, Z) applied to vertices & normals
     3. Backface culling using signed screen-space area
     4. Faces split into 2 triangles each (12 triangles total)
     5. Per-vertex Lambert lighting (light moves in a circle)
     6. Triangle rasterization with barycentric colour
        interpolation (scanline, ImageData) = Gouraud shading
     7. Perspective projection for final screen positions
   ============================================================ */

/* ---------------- tiny vec / mat helpers ---------------- */

function vecSub(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function vecDot(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }
function vecCross(a, b) {
  return [
    a[1] * b[2] - a[2] * b[1],
    a[2] * b[0] - a[0] * b[2],
    a[0] * b[1] - a[1] * b[0]
  ];
}
function vecNormalize(v) {
  const l = Math.hypot(v[0], v[1], v[2]) || 1;
  return [v[0] / l, v[1] / l, v[2] / l];
}

// 3x3 rotation matrix as flat array (row-major)
function matRotX(a) {
  const c = Math.cos(a), s = Math.sin(a);
  return [1, 0, 0,  0, c, -s,  0, s, c];
}
function matRotY(a) {
  const c = Math.cos(a), s = Math.sin(a);
  return [c, 0, s,  0, 1, 0,  -s, 0, c];
}
function matRotZ(a) {
  const c = Math.cos(a), s = Math.sin(a);
  return [c, -s, 0,  s, c, 0,  0, 0, 1];
}
function matMul(a, b) { // a * b, both 3x3 row-major
  const r = new Array(9);
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      r[i * 3 + j] = a[i * 3] * b[j] + a[i * 3 + 1] * b[3 + j] + a[i * 3 + 2] * b[6 + j];
    }
  }
  return r;
}
function matApply(m, v) {
  return [
    m[0] * v[0] + m[1] * v[1] + m[2] * v[2],
    m[3] * v[0] + m[4] * v[1] + m[5] * v[2],
    m[6] * v[0] + m[7] * v[1] + m[8] * v[2]
  ];
}

/* ---------------- cube geometry (object space) ---------------- */

const S = 1; // half-size of cube

// 8 corner vertices
const CUBE_VERTS = [
  [-S, -S, -S], [ S, -S, -S], [ S,  S, -S], [-S,  S, -S], // back  (z = -S)
  [-S, -S,  S], [ S, -S,  S], [ S,  S,  S], [-S,  S,  S]  // front (z = +S)
];

// 6 quad faces, CCW when viewed from outside, with outward normals
const CUBE_QUADS = [
  { idx: [4, 5, 6, 7], n: [0, 0,  1] }, // front
  { idx: [1, 0, 3, 2], n: [0, 0, -1] }, // back
  { idx: [0, 4, 7, 3], n: [-1, 0, 0] }, // left
  { idx: [5, 1, 2, 6], n: [ 1, 0, 0] }, // right
  { idx: [3, 7, 6, 2], n: [0,  1, 0] }, // top
  { idx: [0, 1, 5, 4], n: [0, -1, 0] }  // bottom
];

// Split every quad into 2 triangles (indices into CUBE_QUADS order)
const CUBE_TRIS = [];
for (const q of CUBE_QUADS) {
  CUBE_TRIS.push({ a: q.idx[0], b: q.idx[1], c: q.idx[2], n: q.n });
  CUBE_TRIS.push({ a: q.idx[0], b: q.idx[2], c: q.idx[3], n: q.n });
}

/* ---------------- lighting (Lambert) ---------------- */

const AMBIENT = 0.12;
const BASE_COLOR = [96, 168, 255];   // cool blue base
const LIGHT_COLOR = [255, 244, 214]; // warm light

function lambert(normal, lightDir) {
  const d = Math.max(0, vecDot(normal, lightDir));
  return AMBIENT + (1 - AMBIENT) * d;
}

/* ---------------- perspective projection ---------------- */

const CAM_Z = -4.2;      // camera sits at z = CAM_Z looking down +z
const FOV = 1.9;         // vertical field of view (radians)

function project(p, w, h) {
  const d = p[2] - CAM_Z;           // depth in front of camera
  const scale = (h * 0.5) / Math.tan(FOV * 0.5);
  const x = w * 0.5 + (p[0] * scale) / d;
  const y = h * 0.5 - (p[1] * scale) / d;
  return [x, y, d];
}

/* ---------------- Gouraud triangle rasterizer ----------------
   Scanline fill with barycentric interpolation of per-vertex RGB.
   Writes straight into an ImageData buffer (alpha = 255).      */

function rasterizeGouraudTriangle(buf, W, H,
    p0, c0, p1, c1, p2, c2) {
  let y0 = Math.max(0, Math.ceil(Math.min(p0[1], p1[1], p2[1])));
  let y1 = Math.min(H - 1, Math.floor(Math.max(p0[1], p1[1], p2[1])));
  if (y0 > y1) return;

  const x0 = p0[0], y0f = p0[1], x1 = p1[0], y1f = p1[1], x2 = p2[0], y2f = p2[1];
  const denom = (y1f - y2f) * (x0 - x2) + (x2 - x1) * (y0f - y2f);
  if (Math.abs(denom) < 1e-9) return;
  const invDenom = 1 / denom;

  for (let y = y0; y <= y1; y++) {
    const yc = y + 0.5;
    // barycentric weights vary linearly in y -> evaluate at pixel centre,
    // then march in x with constant increments.
    let w0 = ((y1f - y2f) * (x0 - x2) + (x2 - x1) * (yc - y2f)) * invDenom;
    let w1 = ((y2f - y0f) * (x0 - x2) + (x0 - x1) * (yc - y2f)) * invDenom;
    let w2 = 1 - w0 - w1;
    const dw0dx = (y1f - y2f) * invDenom;
    const dw1dx = (y2f - y0f) * invDenom;

    // x span of the triangle on this scanline
    let xa = Infinity, xb = -Infinity;
    if (y0f <= yc && yc <= y1f) { // edge 0-1
      const t = (yc - y0f);
      xa = Math.min(xa, x0 + (x1 - x0) * t);
      xb = Math.max(xb, x0 + (x1 - x0) * t);
    }
    if (y1f <= yc && yc <= y2f) { // edge 1-2
      const t = (yc - y1f) / ((y2f - y1f) || 1e-9);
      xa = Math.min(xa, x1 + (x2 - x1) * t);
      xb = Math.max(xb, x1 + (x2 - x1) * t);
    }
    if (y2f <= yc && yc <= y0f) { // edge 2-0
      const t = (yc - y2f) / ((y0f - y2f) || 1e-9);
      xa = Math.min(xa, x2 + (x0 - x2) * t);
      xb = Math.max(xb, x2 + (x0 - x2) * t);
    }

    let xs = Math.max(0, Math.ceil(xa - 0.5));
    let xe = Math.min(W - 1, Math.floor(xb - 0.5));
    if (xs > xe) continue;

    // advance weights to first pixel centre
    const xStart = xs + 0.5;
    let dx = xStart - x0;
    w0 += dw0dx * (xStart - x0) * 0; // weights already anchored at x0 via formula below
    // recompute exactly at xStart for numerical cleanliness
    w0 = ((y1f - y2f) * (xStart - x2) + (x2 - x1) * (yc - y2f)) * invDenom;
    w1 = ((y2f - y0f) * (xStart - x2) + (x0 - x1) * (yc - y2f)) * invDenom;
    w2 = 1 - w0 - w1;

    let r = w0 * c0[0] + w1 * c1[0] + w2 * c2[0];
    let g = w0 * c0[1] + w1 * c1[1] + w2 * c2[1];
    let b = w0 * c0[2] + w1 * c1[2] + w2 * c2[2];

    let rowOff = (y * W) << 2;
    for (let x = xs; x <= xe; x++) {
      // guard against 1-pixel edge overshoot from float error
      if (w0 >= -0.002 && w1 >= -0.002 && w2 >= -0.002) {
        const o = rowOff + (x << 2);
        buf[o]     = r < 0 ? 0 : r > 255 ? 255 : r;
        buf[o + 1] = g < 0 ? 0 : g > 255 ? 255 : g;
        buf[o + 2] = b < 0 ? 0 : b > 255 ? 255 : b;
        buf[o + 3] = 255;
      }
      w0 += dw0dx;
      w1 += dw1dx;
      w2 -= dw0dx + dw1dx;
      r += dw0dx * c0[0] + dw1dx * c1[0];
      g += dw0dx * c0[1] + dw1dx * c1[1];
      b += dw0dx * c0[2] + dw1dx * c2[2];
    }
  }
}

/* ---------------- canvas & state ---------------- */

const canvas = document.getElementById('stage');
const ctx = canvas.getContext('2d', { alpha: false });
const fpsEl = document.getElementById('fps');
const modeEl = document.getElementById('mode');

let W = 0, H = 0, DPR = 1;
let imgData = null;

function resize() {
  DPR = Math.min(window.devicePixelRatio || 1, 1.5); // cap DPR for fill-rate
  W = Math.max(2, Math.floor(window.innerWidth * DPR));
  H = Math.max(2, Math.floor(window.innerHeight * DPR));
  canvas.width = W;
  canvas.height = H;
  canvas.style.width = window.innerWidth + 'px';
  canvas.style.height = window.innerHeight + 'px';
  imgData = ctx.createImageData(W, H);
  imgData.data.fill(255); // alpha channel opaque everywhere
}
window.addEventListener('resize', resize);
resize();

let wireframe = false;
let paused = false;
let angleX = 0.55, angleY = 0.35, angleZ = 0.1;

window.addEventListener('keydown', (e) => {
  const k = e.key.toLowerCase();
  if (k === 'w') {
    wireframe = !wireframe;
    modeEl.textContent = wireframe ? 'Wireframe' : 'Gouraud';
  } else if (k === 'p') {
    paused = !paused;
    modeEl.textContent = (wireframe ? 'Wireframe' : 'Gouraud') + (paused ? ' (paused)' : '');
  }
});

/* ---------------- moving light ---------------- */

function getLightDir(t) {
  // light orbits the cube on a tilted circle; direction = normalize(L - P)
  // approximated per-vertex below; here we return light POSITION.
  return [
    Math.cos(t * 0.9) * 3.4,
    Math.sin(t * 0.63) * 2.2 + 0.6,
    Math.sin(t * 0.9) * 3.4 - 1.2
  ];
}

/* ---------------- render ---------------- */

function render(t) {
  const buf = imgData.data;

  // background: vertical gradient (precomputed-ish, cheap per row)
  for (let y = 0; y < H; y++) {
    const k = y / H;
    const r = (5 + 10 * k) | 0;
    const g = (7 + 14 * k) | 0;
    const b = (12 + 26 * k) | 0;
    let o = (y * W) << 2;
    for (let x = 0; x < W; x++, o += 4) {
      buf[o] = r; buf[o + 1] = g; buf[o + 2] = b; buf[o + 3] = 255;
    }
  }

  // 1-2. rotation matrix and rotated vertices / normals
  const m = matMul(matRotY(angleY), matMul(matRotX(angleX), matRotZ(angleZ)));
  const worldV = CUBE_VERTS.map(v => matApply(m, v));
  const proj = worldV.map(v => project(v, W, H));

  const lightPos = getLightDir(t);

  if (wireframe) {
    // rasterize to buffer first, then draw lines on top via 2D API
    ctx.putImageData(imgData, 0, 0);
    ctx.lineWidth = 1.25 * DPR;
    ctx.strokeStyle = 'rgba(140, 200, 255, 0.9)';
    ctx.beginPath();
    for (const q of CUBE_QUADS) {
      const a = proj[q.idx[0]], b = proj[q.idx[1]], c = proj[q.idx[2]], d = proj[q.idx[3]];
      ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]);
      ctx.lineTo(c[0], c[1]); ctx.lineTo(d[0], d[1]);
      ctx.closePath();
    }
    ctx.stroke();
    return;
  }

  // 3-6. triangles: cull -> per-vertex Lambert -> Gouraud raster
  // (sorted back-to-front so shared edges blend nicely; cube is convex
  //  so culling already leaves only front faces, but sort keeps it robust)
  const tris = [];
  for (const tri of CUBE_TRIS) {
    const wa = worldV[tri.a], wb = worldV[tri.b], wc = worldV[tri.c];
    const pa = proj[tri.a], pb = proj[tri.b], pc = proj[tri.c];

    // 3. backface culling: signed screen-space area (CCW = front)
    const area = (pb[0] - pa[0]) * (pc[1] - pa[1]) - (pb[1] - pa[1]) * (pc[0] - pa[0]);
    if (area <= 0) continue;

    const n = matApply(m, tri.n); // rotate face normal into world space
    tris.push({ wa, wb, wc, pa, pb, pc, n, depth: (wa[2] + wb[2] + wc[2]) / 3 });
  }
  tris.sort((a, b) => b.depth - a.depth);

  for (const tr of tris) {
    // 5. per-vertex Lambert: direction from each vertex to moving light
    const la = vecNormalize(vecSub(lightPos, tr.wa));
    const lb = vecNormalize(vecSub(lightPos, tr.wb));
    const lc = vecNormalize(vecSub(lightPos, tr.wc));
    const ia = lambert(tr.n, la), ib = lambert(tr.n, lb), ic = lambert(tr.n, lc);

    const shade = (i) => [
      Math.min(255, BASE_COLOR[0] * i + LIGHT_COLOR[0] * i * i * 0.55),
      Math.min(255, BASE_COLOR[1] * i + LIGHT_COLOR[1] * i * i * 0.55),
      Math.min(255, BASE_COLOR[2] * i + LIGHT_COLOR[2] * i * i * 0.55)
    ];

    // 6. rasterize with interpolated vertex colours (Gouraud)
    rasterizeGouraudTriangle(buf, W, H, tr.pa, shade(ia), tr.pb, shade(ib), tr.pc, shade(ic));
  }

  ctx.putImageData(imgData, 0, 0);

  // subtle edge lines help read the silhouette even in shaded mode
  ctx.lineWidth = 1 * DPR;
  ctx.strokeStyle = 'rgba(10, 16, 28, 0.35)';
  ctx.beginPath();
  for (const q of CUBE_QUADS) {
    const a = proj[q.idx[0]], b = proj[q.idx[1]], c = proj[q.idx[2]], d = proj[q.idx[3]];
    ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]);
    ctx.lineTo(c[0], c[1]); ctx.lineTo(d[0], d[1]);
    ctx.closePath();
  }
  ctx.stroke();
}

/* ---------------- main loop + FPS ---------------- */

let lastTime = performance.now();
let fpsSmooth = 0;
let fpsTimer = 0;
let simTime = 0;

function frame(now) {
  const dt = Math.min(0.1, (now - lastTime) / 1000);
  lastTime = now;

  // FPS (smoothed, updated 4x/sec)
  if (dt > 0) {
    const inst = 1 / dt;
    fpsSmooth = fpsSmooth === 0 ? inst : fpsSmooth * 0.9 + inst * 0.1;
  }
  fpsTimer += dt;
  if (fpsTimer >= 0.25) {
    fpsTimer = 0;
    fpsEl.textContent = Math.round(fpsSmooth);
  }

  if (!paused) {
    simTime += dt;
    angleY += dt * 0.7;
    angleX += dt * 0.35;
    angleZ += dt * 0.18;
  }

  render(simTime);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
</script>
